import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

// Scenario: A vendor under review cannot be edited (VEN-09)
// Creates a vendor, moves it to "in_review" via submit, then attempts a contact email change.
// The vendor is created with a unique name so parallel runs against the shared database do not collide.

test.describe("vendor locking", () => {
  test(
    "a vendor under review cannot be edited",
    { tag: "@VEN-09" },
    async ({ apiAs, factory }) => {
      // Arrange: a vendor in status "in_review" for the member's tenant
      const member = await apiAs("member");
      const vendor = await factory.vendor({ status: "in_review" });

      // Act
      const response = await member.patch(`/api/vendors/${vendor.id}`, {
        data: { contact_email: "billing@acmefreight.example" },
      });

      // Assert
      const body = await expectStatus<{ error: { code: string } }>(response, 409);
      expect(body.error.code).toBe("vendor_locked");
    },
  );
});
